-- =============================================================================
-- 0003a_map_cells.sql — the plots of the "Light up Armenia" map.
--
-- Only the table: 0004_cells_seed.sql (generated by tools/make_map.py) fills
-- it, and 0005_lights.sql builds everything else on top of it.
-- Apply order: 0003_admin, 0003a_map_cells, 0004_cells_seed, 0005_lights.
--
-- id = row * 135 + col of the 2x2 km grid. town_index = index of the nearest
-- town in the frontend's town list, -1 when the plot is not near a town.
-- Province codes: yer ara arm ag kt gr sh lo tv vd su.
-- =============================================================================

create table public.map_cells (
  id         integer primary key,
  province   text    not null,
  town_index integer not null default -1,
  constraint map_cells_id_range      check (id >= 0 and id < 1000000),
  constraint map_cells_province_enum check (province in ('yer', 'ara', 'arm', 'ag', 'kt', 'gr', 'sh', 'lo', 'tv', 'vd', 'su')),
  constraint map_cells_town_index    check (town_index >= -1 and town_index < 1000)
);

-- RLS on, no policies; the browser reads plots only through get_map()/get_cell().
alter table public.map_cells enable row level security;
revoke all on table public.map_cells from public, anon, authenticated;
grant select on table public.map_cells to service_role;
